(7229261, 1116576, 128323, '<td valign="top">Way to go Jake!!</td>', 'Way to go Jake!!', '2014-06-16 06:58:39.000000', NULL, 0),
(7229271, 1116138, 135744, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Kroburg:</b></div><hr/><i> Hey Paul, great result!! Congrats on a magnificent score and the Blue!. This proves you get the best result when NOT asking me for advise ;-) </i></td></tr></table> <br/> <br/>Ha, I didn''t need advice choosing my entry for this one as I only had one contender. I must confess it took my by surprise as I had just popped out during my lunch break to take a few shots and didn''t really think I had anything worth shouting about. How wrong I was:)</td>', 'Originally posted by Kroburg: Hey Paul, great result!! Congrats on a magnificent score and the Blue!. This proves you get the best result when NOT asking me for advise ;-)   Ha, I didn''t need advice choosing my entry for this one as I only had one contender. I must confess it took my by surprise as I had just popped out during my lunch break to take a few shots and didn''t really think I had anything worth shouting about. How wrong I was:)', '2014-06-16 07:08:49.000000', NULL, 0),
(7229275, 1116576, 156466, '<td valign="top">Thanks, everyone.  Would have loved to have been able to get a closer shot of this guy, but he was behind an electric fence in a field, standing a good distance off the road, so I was fortunate to get enough detail in the crop I had at 200mm.  He only looked up for about 10 seconds, then went back to eating before roaming away.</td>', 'Thanks, everyone.  Would have loved to have been able to get a closer shot of this guy, but he was behind an electric fence in a field, standing a good distance off the road, so I was fortunate to get enough detail in the crop I had at 200mm.  He only looked up for about 10 seconds, then went back to eating before roaming away.', '2014-06-16 07:11:14.000000', NULL, 0),
(7229285, 1116576, 153814, '<td valign="top">Nice finish, well done.</td>', 'Nice finish, well done.', '2014-06-16 08:08:20.000000', NULL, 0),
